static void tf450_init(void)
{
    int i;
    struct dsi_cmd_packet tf450_display_on = {0x05, 0x29, 0x00};

    for (i = 0; i < ARRAY_SIZE(fitipower_tf450_cmd_list); i++)
        dsi_write_cmd(&fitipower_tf450_cmd_list[i]);

    msleep(120);
    dsi_write_cmd(&tf450_display_on);
}

static inline int m_gpio_request(int gpio, const char *name)
{
    if (gpio < 0)
        return 0;

    int ret = gpio_request(gpio, name);
    if (ret) {
        char buf[20];
        printk(KERN_ERR "tf450: failed to request %s: %s\n", name, gpio_to_str(gpio, buf));
        return ret;
    }

    return 0;
}

static inline void m_gpio_free(int gpio)
{
    if (gpio >= 0)
        gpio_free(gpio);
}

static inline void m_gpio_direction_output(int gpio, int value)
{
    if (gpio >= 0)
        gpio_direction_output(gpio, value);
}

static inline void m_gpio_direction_input(int gpio)
{
    if (gpio >= 0)
        gpio_direction_input(gpio);
}

static int tf450_power_on(struct lcdc *lcdc)
{
    if (tf450_regulator)
        regulator_enable(tf450_regulator);

    m_gpio_direction_output(gpio_lcd_power_en, 0);
    msleep(5);

    m_gpio_direction_output(gpio_lcd_rst, 0);
    msleep(5);
    m_gpio_direction_output(gpio_lcd_rst, 1);
    msleep(60);

    m_gpio_direction_output(gpio_lcd_backlight_en, 1);

    return 0;
}

static int tf450_power_off(struct lcdc *lcdc)
{
    if (tf450_regulator)
        regulator_disable(tf450_regulator);

    m_gpio_direction_output(gpio_lcd_backlight_en, 0);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    m_gpio_direction_output(gpio_lcd_power_en, 1);

    return 0;
}

